161:     /// let viewport = Viewport::Fixed(Rect::new(0, 0, 10, 10));
162:     /// let terminal = Terminal::with_options(backend, TerminalOptions { viewport })?;
163:     /// # std::io::Result::Ok(())
164:     /// ```
165:     pub fn with_options(mut backend: B, options: TerminalOptions) -> Result<Self, B::Error> {
166:         let area = match options.viewport {
167:             Viewport::Fullscreen | Viewport::Inline(_) => backend.size()?.into(),
168:             Viewport::Fixed(area) => area,
169:         };
170:         let (viewport_area, cursor_pos) = match options.viewport {
171:             Viewport::Fullscreen => (area, Position::ORIGIN),
172:             Viewport::Inline(height) => {
173:                 compute_inline_size(&mut backend, height, area.as_size(), 0)?
174:             }
175:             Viewport::Fixed(area) => (area, area.as_position()),
176:         };
177:         Ok(Self {
178:             backend,
179:             buffers: [Buffer::empty(viewport_area), Buffer::empty(viewport_area)],
180:             current: 0,
181:             hidden_cursor: false,
182:             viewport: options.viewport,
183:             viewport_area,
184:             last_known_area: area,
185:             last_known_cursor_pos: cursor_pos,
186:             frame_count: 0,
187:         })
188:     }
