190:     /// Get a Frame object which provides a consistent view into the terminal state for rendering.
191:     pub const fn get_frame(&mut self) -> Frame<'_> {
192:         let count = self.frame_count;
193:         Frame {
194:             cursor_position: None,
195:             viewport_area: self.viewport_area,
196:             buffer: self.current_buffer_mut(),
197:             count,
198:         }
