216:     /// Obtains a difference between the previous and the current buffer and passes it to the
217:     /// current backend for drawing.
218:     pub fn flush(&mut self) -> Result<(), B::Error> {
219:         let previous_buffer = &self.buffers[1 - self.current];
220:         let current_buffer = &self.buffers[self.current];
221:         let updates = previous_buffer.diff(current_buffer);
222:         if let Some((col, row, _)) = updates.last() {
223:             self.last_known_cursor_pos = Position { x: *col, y: *row };
224:         }
225:         self.backend.draw(updates.into_iter())
226:     }
