228:     /// Updates the Terminal so that internal buffers match the requested area.
229:     ///
230:     /// Requested area will be saved to remain consistent when rendering. This leads to a full clear
231:     /// of the screen.
232:     pub fn resize(&mut self, area: Rect) -> Result<(), B::Error> {
233:         let next_area = match self.viewport {
234:             Viewport::Inline(height) => {
235:                 let offset_in_previous_viewport = self
236:                     .last_known_cursor_pos
237:                     .y
238:                     .saturating_sub(self.viewport_area.top());
239:                 compute_inline_size(
240:                     &mut self.backend,
241:                     height,
242:                     area.as_size(),
243:                     offset_in_previous_viewport,
244:                 )?
245:                 .0
246:             }
247:             Viewport::Fixed(_) | Viewport::Fullscreen => area,
248:         };
249:         self.set_viewport_area(next_area);
250:         self.clear()?;
251: 
252:         self.last_known_area = area;
253:         Ok(())
254:     }
