274:     /// Draws a single frame to the terminal.
275:     ///
276:     /// Returns a [`CompletedFrame`] if successful, otherwise a [`std::io::Error`].
277:     ///
278:     /// If the render callback passed to this method can fail, use [`try_draw`] instead.
279:     ///
280:     /// Applications should call `draw` or [`try_draw`] in a loop to continuously render the
281:     /// terminal. These methods are the main entry points for drawing to the terminal.
282:     ///
283:     /// [`try_draw`]: Terminal::try_draw
284:     ///
285:     /// This method will:
286:     ///
287:     /// - autoresize the terminal if necessary
288:     /// - call the render callback, passing it a [`Frame`] reference to render to
289:     /// - flush the current internal state by copying the current buffer to the backend
290:     /// - move the cursor to the last known position if it was set during the rendering closure
291:     /// - return a [`CompletedFrame`] with the current buffer and the area of the terminal
292:     ///
293:     /// The [`CompletedFrame`] returned by this method can be useful for debugging or testing
294:     /// purposes, but it is often not used in regular applications.
295:     ///
296:     /// The render callback should fully render the entire frame when called, including areas that
297:     /// are unchanged from the previous frame. This is because each frame is compared to the
298:     /// previous frame to determine what has changed, and only the changes are written to the
299:     /// terminal. If the render callback does not fully render the frame, the terminal will not be
300:     /// in a consistent state.
301:     ///
302:     /// # Examples
303:     ///
304:     /// ```rust,ignore
305:     /// # let backend = ratatui::backend::TestBackend::new(10, 10);
306:     /// # let mut terminal = ratatui::Terminal::new(backend)?;
307:     /// use ratatui::{layout::Position, widgets::Paragraph};
308:     ///
309:     /// // with a closure
310:     /// terminal.draw(|frame| {
311:     ///     let area = frame.area();
312:     ///     frame.render_widget(Paragraph::new("Hello World!"), area);
313:     ///     frame.set_cursor_position(Position { x: 0, y: 0 });
314:     /// })?;
315:     ///
316:     /// // or with a function
317:     /// terminal.draw(render)?;
318:     ///
319:     /// fn render(frame: &mut ratatui::Frame) {
320:     ///     frame.render_widget(Paragraph::new("Hello World!"), frame.area());
321:     /// }
322:     /// # std::io::Result::Ok(())
323:     /// ```
324:     pub fn draw<F>(&mut self, render_callback: F) -> Result<CompletedFrame<'_>, B::Error>
325:     where
326:         F: FnOnce(&mut Frame),
327:     {
328:         self.try_draw(|frame| {
329:             render_callback(frame);
330:             Ok::<(), B::Error>(())
331:         })
332:     }
