334:     /// Tries to draw a single frame to the terminal.
335:     ///
336:     /// Returns [`Result::Ok`] containing a [`CompletedFrame`] if successful, otherwise
337:     /// [`Result::Err`] containing the [`std::io::Error`] that caused the failure.
338:     ///
339:     /// This is the equivalent of [`Terminal::draw`] but the render callback is a function or
340:     /// closure that returns a `Result` instead of nothing.
341:     ///
342:     /// Applications should call `try_draw` or [`draw`] in a loop to continuously render the
343:     /// terminal. These methods are the main entry points for drawing to the terminal.
344:     ///
345:     /// [`draw`]: Terminal::draw
346:     ///
347:     /// This method will:
348:     ///
349:     /// - autoresize the terminal if necessary
350:     /// - call the render callback, passing it a [`Frame`] reference to render to
351:     /// - flush the current internal state by copying the current buffer to the backend
352:     /// - move the cursor to the last known position if it was set during the rendering closure
353:     /// - return a [`CompletedFrame`] with the current buffer and the area of the terminal
354:     ///
355:     /// The render callback passed to `try_draw` can return any [`Result`] with an error type that
356:     /// can be converted into an [`std::io::Error`] using the [`Into`] trait. This makes it possible
357:     /// to use the `?` operator to propagate errors that occur during rendering. If the render
358:     /// callback returns an error, the error will be returned from `try_draw` as an
359:     /// [`std::io::Error`] and the terminal will not be updated.
360:     ///
361:     /// The [`CompletedFrame`] returned by this method can be useful for debugging or testing
362:     /// purposes, but it is often not used in regular applications.
363:     ///
364:     /// The render callback should fully render the entire frame when called, including areas that
365:     /// are unchanged from the previous frame. This is because each frame is compared to the
366:     /// previous frame to determine what has changed, and only the changes are written to the
367:     /// terminal. If the render function does not fully render the frame, the terminal will not be
368:     /// in a consistent state.
369:     ///
370:     /// # Examples
371:     ///
372:     /// ```ignore
373:     /// # use ratatui::layout::Position;;
374:     /// # let backend = ratatui::backend::TestBackend::new(10, 10);
375:     /// # let mut terminal = ratatui::Terminal::new(backend)?;
376:     /// use std::io;
377:     ///
378:     /// use ratatui::widgets::Paragraph;
379:     ///
380:     /// // with a closure
381:     /// terminal.try_draw(|frame| {
382:     ///     let value: u8 = "not a number".parse().map_err(io::Error::other)?;
383:     ///     let area = frame.area();
384:     ///     frame.render_widget(Paragraph::new("Hello World!"), area);
385:     ///     frame.set_cursor_position(Position { x: 0, y: 0 });
386:     ///     io::Result::Ok(())
387:     /// })?;
388:     ///
389:     /// // or with a function
390:     /// terminal.try_draw(render)?;
391:     ///
392:     /// fn render(frame: &mut ratatui::Frame) -> io::Result<()> {
393:     ///     let value: u8 = "not a number".parse().map_err(io::Error::other)?;
394:     ///     frame.render_widget(Paragraph::new("Hello World!"), frame.area());
395:     ///     Ok(())
396:     /// }
397:     /// # io::Result::Ok(())
398:     /// ```
399:     pub fn try_draw<F, E>(&mut self, render_callback: F) -> Result<CompletedFrame<'_>, B::Error>
400:     where
401:         F: FnOnce(&mut Frame) -> Result<(), E>,
402:         E: Into<B::Error>,
403:     {
404:         // Autoresize - otherwise we get glitches if shrinking or potential desync between widgets
405:         // and the terminal (if growing), which may OOB.
406:         self.autoresize()?;
407: 
408:         let mut frame = self.get_frame();
409: 
410:         render_callback(&mut frame).map_err(Into::into)?;
411: 
412:         // We can't change the cursor position right away because we have to flush the frame to
413:         // stdout first. But we also can't keep the frame around, since it holds a &mut to
414:         // Buffer. Thus, we're taking the important data out of the Frame and dropping it.
415:         let cursor_position = frame.cursor_position;
416: 
417:         // Draw to stdout
418:         self.flush()?;
419: 
420:         match cursor_position {
421:             None => self.hide_cursor()?,
422:             Some(position) => {
423:                 self.show_cursor()?;
424:                 self.set_cursor_position(position)?;
425:             }
426:         }
427: 
428:         self.swap_buffers();
429: 
430:         // Flush
431:         self.backend.flush()?;
432: 
433:         let completed_frame = CompletedFrame {
434:             buffer: &self.buffers[1 - self.current],
435:             area: self.last_known_area,
436:             count: self.frame_count,
437:         };
438: 
439:         // increment frame count before returning from draw
440:         self.frame_count = self.frame_count.wrapping_add(1);
441: 
442:         Ok(completed_frame)
443:     }
444: 
445:     /// Hides the cursor.
446:     pub fn hide_cursor(&mut self) -> Result<(), B::Error> {
447:         self.backend.hide_cursor()?;
448:         self.hidden_cursor = true;
449:         Ok(())
450:     }
451: 
452:     /// Shows the cursor.
453:     pub fn show_cursor(&mut self) -> Result<(), B::Error> {
454:         self.backend.show_cursor()?;
455:         self.hidden_cursor = false;
456:         Ok(())
457:     }
458: 
459:     /// Gets the current cursor position.
460:     ///
461:     /// This is the position of the cursor after the last draw call and is returned as a tuple of
462:     /// `(x, y)` coordinates.
463:     #[deprecated = "use `get_cursor_position()` instead which returns `Result<Position>`"]
464:     pub fn get_cursor(&mut self) -> Result<(u16, u16), B::Error> {
465:         let Position { x, y } = self.get_cursor_position()?;
466:         Ok((x, y))
467:     }
468: 
469:     /// Sets the cursor position.
470:     #[deprecated = "use `set_cursor_position((x, y))` instead which takes `impl Into<Position>`"]
471:     pub fn set_cursor(&mut self, x: u16, y: u16) -> Result<(), B::Error> {
472:         self.set_cursor_position(Position { x, y })
473:     }
474: 
475:     /// Gets the current cursor position.
476:     ///
477:     /// This is the position of the cursor after the last draw call.
478:     pub fn get_cursor_position(&mut self) -> Result<Position, B::Error> {
479:         self.backend.get_cursor_position()
480:     }
481: 
482:     /// Sets the cursor position.
483:     pub fn set_cursor_position<P: Into<Position>>(&mut self, position: P) -> Result<(), B::Error> {
484:         let position = position.into();
485:         self.backend.set_cursor_position(position)?;
486:         self.last_known_cursor_pos = position;
487:         Ok(())
488:     }
489: 
490:     /// Clear the terminal and force a full redraw on the next draw call.
491:     pub fn clear(&mut self) -> Result<(), B::Error> {
492:         match self.viewport {
493:             Viewport::Fullscreen => self.backend.clear_region(ClearType::All)?,
494:             Viewport::Inline(_) => {
495:                 self.backend
496:                     .set_cursor_position(self.viewport_area.as_position())?;
497:                 self.backend.clear_region(ClearType::AfterCursor)?;
498:             }
499:             Viewport::Fixed(_) => {
500:                 let area = self.viewport_area;
501:                 for y in area.top()..area.bottom() {
502:                     self.backend.set_cursor_position(Position { x: 0, y })?;
503:                     self.backend.clear_region(ClearType::AfterCursor)?;
504:                 }
505:             }
506:         }
507:         // Reset the back buffer to make sure the next update will redraw everything.
508:         self.buffers[1 - self.current].reset();
509:         Ok(())
510:     }
511: 
512:     /// Clears the inactive buffer and swaps it with the current buffer
513:     pub fn swap_buffers(&mut self) {
514:         self.buffers[1 - self.current].reset();
515:         self.current = 1 - self.current;
516:     }
517: 
518:     /// Queries the real size of the backend.
519:     pub fn size(&self) -> Result<Size, B::Error> {
520:         self.backend.size()
521:     }
522: 
523:     /// Insert some content before the current inline viewport. This has no effect when the
524:     /// viewport is not inline.
525:     ///
526:     /// The `draw_fn` closure will be called to draw into a writable `Buffer` that is `height`
527:     /// lines tall. The content of that `Buffer` will then be inserted before the viewport.
528:     ///
529:     /// If the viewport isn't yet at the bottom of the screen, inserted lines will push it towards
530:     /// the bottom. Once the viewport is at the bottom of the screen, inserted lines will scroll
531:     /// the area of the screen above the viewport upwards.
532:     ///
533:     /// Before:
534:     /// ```ignore
535:     /// +---------------------+
536:     /// | pre-existing line 1 |
537:     /// | pre-existing line 2 |
538:     /// +---------------------+
539:     /// |       viewport      |
540:     /// +---------------------+
541:     /// |                     |
542:     /// |                     |
543:     /// +---------------------+
544:     /// ```
545:     ///
546:     /// After inserting 2 lines:
547:     /// ```ignore
548:     /// +---------------------+
549:     /// | pre-existing line 1 |
550:     /// | pre-existing line 2 |
551:     /// |   inserted line 1   |
552:     /// |   inserted line 2   |
553:     /// +---------------------+
554:     /// |       viewport      |
555:     /// +---------------------+
556:     /// +---------------------+
557:     /// ```
558:     ///
559:     /// After inserting 2 more lines:
560:     /// ```ignore
561:     /// +---------------------+
562:     /// | pre-existing line 2 |
563:     /// |   inserted line 1   |
564:     /// |   inserted line 2   |
565:     /// |   inserted line 3   |
566:     /// |   inserted line 4   |
567:     /// +---------------------+
568:     /// |       viewport      |
569:     /// +---------------------+
570:     /// ```
571:     ///
572:     /// If more lines are inserted than there is space on the screen, then the top lines will go
573:     /// directly into the terminal's scrollback buffer. At the limit, if the viewport takes up the
574:     /// whole screen, all lines will be inserted directly into the scrollback buffer.
575:     ///
576:     /// # Examples
577:     ///
578:     /// ## Insert a single line before the current viewport
579:     ///
580:     /// ```rust,ignore
581:     /// use ratatui::{
582:     ///     backend::TestBackend,
583:     ///     style::{Color, Style},
584:     ///     text::{Line, Span},
585:     ///     widgets::{Paragraph, Widget},
586:     ///     Terminal,
587:     /// };
588:     /// # let backend = TestBackend::new(10, 10);
589:     /// # let mut terminal = Terminal::new(backend).unwrap();
590:     /// terminal.insert_before(1, |buf| {
591:     ///     Paragraph::new(Line::from(vec![
592:     ///         Span::raw("This line will be added "),
593:     ///         Span::styled("before", Style::default().fg(Color::Blue)),
594:     ///         Span::raw(" the current viewport"),
595:     ///     ]))
596:     ///     .render(buf.area, buf);
597:     /// });
598:     /// ```
599:     pub fn insert_before<F>(&mut self, height: u16, draw_fn: F) -> Result<(), B::Error>
600:     where
601:         F: FnOnce(&mut Buffer),
602:     {
603:         match self.viewport {
604:             #[cfg(feature = "scrolling-regions")]
605:             Viewport::Inline(_) => self.insert_before_scrolling_regions(height, draw_fn),
606:             #[cfg(not(feature = "scrolling-regions"))]
607:             Viewport::Inline(_) => self.insert_before_no_scrolling_regions(height, draw_fn),
608:             _ => Ok(()),
609:         }
610:     }
611: 
612:     /// Implement `Self::insert_before` using standard backend capabilities.
613:     #[cfg(not(feature = "scrolling-regions"))]
614:     fn insert_before_no_scrolling_regions(
615:         &mut self,
616:         height: u16,
617:         draw_fn: impl FnOnce(&mut Buffer),
618:     ) -> Result<(), B::Error> {
619:         // The approach of this function is to first render all of the lines to insert into a
620:         // temporary buffer, and then to loop drawing chunks from the buffer to the screen. drawing
621:         // this buffer onto the screen.
622:         let area = Rect {
623:             x: 0,
624:             y: 0,
625:             width: self.viewport_area.width,
626:             height,
627:         };
628:         let mut buffer = Buffer::empty(area);
629:         draw_fn(&mut buffer);
630:         let mut buffer = buffer.content.as_slice();
631: 
632:         // Use i32 variables so we don't have worry about overflowed u16s when adding, or about
633:         // negative results when subtracting.
634:         let mut drawn_height: i32 = self.viewport_area.top().into();
635:         let mut buffer_height: i32 = height.into();
636:         let viewport_height: i32 = self.viewport_area.height.into();
637:         let screen_height: i32 = self.last_known_area.height.into();
638: 
639:         // The algorithm here is to loop, drawing large chunks of text (up to a screen-full at a
640:         // time), until the remainder of the buffer plus the viewport fits on the screen. We choose
641:         // this loop condition because it guarantees that we can write the remainder of the buffer
642:         // with just one call to Self::draw_lines().
643:         while buffer_height + viewport_height > screen_height {
644:             // We will draw as much of the buffer as possible on this iteration in order to make
645:             // forward progress. So we have:
646:             //
647:             //     to_draw = min(buffer_height, screen_height)
648:             //
649:             // We may need to scroll the screen up to make room to draw. We choose the minimal
650:             // possible scroll amount so we don't end up with the viewport sitting in the middle of
651:             // the screen when this function is done. The amount to scroll by is:
652:             //
653:             //     scroll_up = max(0, drawn_height + to_draw - screen_height)
654:             //
655:             // We want `scroll_up` to be enough so that, after drawing, we have used the whole
656:             // screen (drawn_height - scroll_up + to_draw = screen_height). However, there might
657:             // already be enough room on the screen to draw without scrolling (drawn_height +
658:             // to_draw <= screen_height). In this case, we just don't scroll at all.
659:             let to_draw = buffer_height.min(screen_height);
660:             let scroll_up = 0.max(drawn_height + to_draw - screen_height);
661:             self.scroll_up(scroll_up as u16)?;
662:             buffer = self.draw_lines((drawn_height - scroll_up) as u16, to_draw as u16, buffer)?;
663:             drawn_height += to_draw - scroll_up;
664:             buffer_height -= to_draw;
665:         }
666: 
667:         // There is now enough room on the screen for the remaining buffer plus the viewport,
668:         // though we may still need to scroll up some of the existing text first. It's possible
669:         // that by this point we've drained the buffer, but we may still need to scroll up to make
670:         // room for the viewport.
671:         //
672:         // We want to scroll up the exact amount that will leave us completely filling the screen.
673:         // However, it's possible that the viewport didn't start on the bottom of the screen and
674:         // the added lines weren't enough to push it all the way to the bottom. We deal with this
675:         // case by just ensuring that our scroll amount is non-negative.
676:         //
677:         // We want:
678:         //   screen_height = drawn_height - scroll_up + buffer_height + viewport_height
679:         // Or, equivalently:
680:         //   scroll_up = drawn_height + buffer_height + viewport_height - screen_height
681:         let scroll_up = 0.max(drawn_height + buffer_height + viewport_height - screen_height);
682:         self.scroll_up(scroll_up as u16)?;
683:         self.draw_lines(
684:             (drawn_height - scroll_up) as u16,
685:             buffer_height as u16,
686:             buffer,
687:         )?;
688:         drawn_height += buffer_height - scroll_up;
689: 
690:         self.set_viewport_area(Rect {
691:             y: drawn_height as u16,
692:             ..self.viewport_area
693:         });
694: 
695:         // Clear the viewport off the screen. We didn't clear earlier for two reasons. First, it
696:         // wasn't necessary because the buffer we drew out of isn't sparse, so it overwrote
697:         // whatever was on the screen. Second, there is a weird bug with tmux where a full screen
698:         // clear plus immediate scrolling causes some garbage to go into the scrollback.
699:         self.clear()?;
700: 
701:         Ok(())
702:     }
703: 
704:     /// Implement `Self::insert_before` using scrolling regions.
705:     ///
706:     /// If a terminal supports scrolling regions, it means that we can define a subset of rows of
707:     /// the screen, and then tell the terminal to scroll up or down just within that region. The
708:     /// rows outside of the region are not affected.
709:     ///
710:     /// This function utilizes this feature to avoid having to redraw the viewport. This is done
711:     /// either by splitting the screen at the top of the viewport, and then creating a gap by
712:     /// either scrolling the viewport down, or scrolling the area above it up. The lines to insert
713:     /// are then drawn into the gap created.
714:     #[cfg(feature = "scrolling-regions")]
715:     fn insert_before_scrolling_regions(
716:         &mut self,
717:         mut height: u16,
718:         draw_fn: impl FnOnce(&mut Buffer),
719:     ) -> Result<(), B::Error> {
720:         // The approach of this function is to first render all of the lines to insert into a
721:         // temporary buffer, and then to loop drawing chunks from the buffer to the screen. drawing
722:         // this buffer onto the screen.
723:         let area = Rect {
724:             x: 0,
725:             y: 0,
726:             width: self.viewport_area.width,
727:             height,
728:         };
729:         let mut buffer = Buffer::empty(area);
730:         draw_fn(&mut buffer);
731:         let mut buffer = buffer.content.as_slice();
732: 
733:         // Handle the special case where the viewport takes up the whole screen.
734:         if self.viewport_area.height == self.last_known_area.height {
735:             // "Borrow" the top line of the viewport. Draw over it, then immediately scroll it into
736:             // scrollback. Do this repeatedly until the whole buffer has been put into scrollback.
737:             let mut first = true;
738:             while !buffer.is_empty() {
739:                 buffer = if first {
740:                     self.draw_lines(0, 1, buffer)?
741:                 } else {
742:                     self.draw_lines_over_cleared(0, 1, buffer)?
743:                 };
744:                 first = false;
745:                 self.backend.scroll_region_up(0..1, 1)?;
746:             }
747: 
748:             // Redraw the top line of the viewport.
749:             let width = self.viewport_area.width as usize;
750:             let top_line = self.buffers[1 - self.current].content[0..width].to_vec();
751:             self.draw_lines_over_cleared(0, 1, &top_line)?;
752:             return Ok(());
753:         }
754: 
755:         // Handle the case where the viewport isn't yet at the bottom of the screen.
756:         {
757:             let viewport_top = self.viewport_area.top();
758:             let viewport_bottom = self.viewport_area.bottom();
759:             let screen_bottom = self.last_known_area.bottom();
760:             if viewport_bottom < screen_bottom {
761:                 let to_draw = height.min(screen_bottom - viewport_bottom);
762:                 self.backend
763:                     .scroll_region_down(viewport_top..viewport_bottom + to_draw, to_draw)?;
764:                 buffer = self.draw_lines_over_cleared(viewport_top, to_draw, buffer)?;
765:                 self.set_viewport_area(Rect {
766:                     y: viewport_top + to_draw,
767:                     ..self.viewport_area
768:                 });
769:                 height -= to_draw;
770:             }
771:         }
772: 
773:         let viewport_top = self.viewport_area.top();
774:         while height > 0 {
775:             let to_draw = height.min(viewport_top);
776:             self.backend.scroll_region_up(0..viewport_top, to_draw)?;
777:             buffer = self.draw_lines_over_cleared(viewport_top - to_draw, to_draw, buffer)?;
778:             height -= to_draw;
779:         }
780: 
781:         Ok(())
782:     }
783: 
784:     /// Draw lines at the given vertical offset. The slice of cells must contain enough cells
785:     /// for the requested lines. A slice of the unused cells are returned.
786:     fn draw_lines<'a>(
787:         &mut self,
788:         y_offset: u16,
789:         lines_to_draw: u16,
790:         cells: &'a [Cell],
791:     ) -> Result<&'a [Cell], B::Error> {
792:         let width: usize = self.last_known_area.width.into();
793:         let (to_draw, remainder) = cells.split_at(width * lines_to_draw as usize);
794:         if lines_to_draw > 0 {
795:             let iter = to_draw
796:                 .iter()
797:                 .enumerate()
798:                 .map(|(i, c)| ((i % width) as u16, y_offset + (i / width) as u16, c));
799:             self.backend.draw(iter)?;
800:             self.backend.flush()?;
801:         }
802:         Ok(remainder)
803:     }
804: 
805:     /// Draw lines at the given vertical offset, assuming that the lines they are replacing on the
806:     /// screen are cleared. The slice of cells must contain enough cells for the requested lines. A
807:     /// slice of the unused cells are returned.
808:     #[cfg(feature = "scrolling-regions")]
809:     fn draw_lines_over_cleared<'a>(
810:         &mut self,
811:         y_offset: u16,
812:         lines_to_draw: u16,
813:         cells: &'a [Cell],
814:     ) -> Result<&'a [Cell], B::Error> {
815:         let width: usize = self.last_known_area.width.into();
816:         let (to_draw, remainder) = cells.split_at(width * lines_to_draw as usize);
817:         if lines_to_draw > 0 {
818:             let area = Rect::new(0, y_offset, width as u16, y_offset + lines_to_draw);
819:             let old = Buffer::empty(area);
820:             let new = Buffer {
821:                 area,
822:                 content: to_draw.to_vec(),
823:             };
824:             self.backend.draw(old.diff(&new).into_iter())?;
825:             self.backend.flush()?;
826:         }
827:         Ok(remainder)
828:     }
829: 
830:     /// Scroll the whole screen up by the given number of lines.
831:     #[cfg(not(feature = "scrolling-regions"))]
832:     fn scroll_up(&mut self, lines_to_scroll: u16) -> Result<(), B::Error> {
833:         if lines_to_scroll > 0 {
834:             self.set_cursor_position(Position::new(
835:                 0,
836:                 self.last_known_area.height.saturating_sub(1),
837:             ))?;
838:             self.backend.append_lines(lines_to_scroll)?;
839:         }
840:         Ok(())
841:     }
842: }
843: 
844: fn compute_inline_size<B: Backend>(
845:     backend: &mut B,
846:     height: u16,
847:     size: Size,
848:     offset_in_previous_viewport: u16,
849: ) -> Result<(Rect, Position), B::Error> {
850:     let pos = backend.get_cursor_position()?;
851:     let mut row = pos.y;
852: 
853:     let max_height = size.height.min(height);
854: 
855:     let lines_after_cursor = height
856:         .saturating_sub(offset_in_previous_viewport)
857:         .saturating_sub(1);
858: 
859:     backend.append_lines(lines_after_cursor)?;
860: 
861:     let available_lines = size.height.saturating_sub(row).saturating_sub(1);
862:     let missing_lines = lines_after_cursor.saturating_sub(available_lines);
863:     if missing_lines > 0 {
864:         row = row.saturating_sub(missing_lines);
865:     }
866:     row = row.saturating_sub(offset_in_previous_viewport);
867: 
868:     Ok((
869:         Rect {
870:             x: 0,
871:             y: row,
872:             width: size.width,
873:             height: max_height,
874:         },
875:         pos,
876:     ))
877: }
